scripts.script:
if (args.isHit && !args.target.system.martial.stanceActive) {
    const msg = `<div class="xjzl-chat-card" style="margin-left: 5px; border-left: 4px solid #2980b9; background: rgba(41,128,185,0.05); padding: 5px;">
        <div style="font-weight:bold; color:#2980b9;"><i class="fas fa-wind"></i> 飞花似梦</div>
        <div>目标 <b>${args.target.name}</b> 被击飞 1 米！请手动调整其位置。</div>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (actor.system.martial.stanceActive && actor.system.martial.stanceItemId === thisItem.id) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const healVal = 5 + (lvl - 1) * 5;
    const msg = `<div class="xjzl-chat-card" style="margin-left: 5px; border-left: 4px solid #27ae60; background: rgba(39,174,96,0.05); padding: 5px;">
        <div style="font-weight:bold; color:#27ae60;"><i class="fas fa-heart"></i> 春雨绵绵</div>
        <div style="font-size:0.9em; color:#555;">你正维持架招，请手动为 3 米范围内未濒死的友方回复 <b>${healVal}</b> 点气血。</div>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const jinshi = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "jinshi"));
    if (jinshi) {
        jinshi.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, jinshi);
    }
}

const stanceId = actor.system.martial.stance;
const moveData = thisItem.system.moves.find(m => m.id === stanceId);
const lvl = Math.max(1, moveData?.computedLevel || 1);
if (Macros.checkStance(actor, args)) {
    const bonus = 1 + (lvl - 1);
    const rounds = 1 + (lvl - 1);
    const effect = thisItem.effects.getName("清音").toObject();
    effect.duration.rounds = rounds;
    effect.changes[0].value = String(bonus);
    await game.xjzl.api.effects.addEffect(actor, effect);
}

const getTag = (x, e) => {
    if (x >= 1000 && e < 200) return 'xia';
    if (x >= 500 && e < 100) return 'xia';
    if (x >= 100 && e < 50) return 'xia';
    if (e >= 1000 && x < 200) return 'e';
    if (e >= 500 && x < 100) return 'e';
    if (e >= 100 && x < 50) return 'e';
    return 'none';
};
const myTag = getTag(actor.system.social.xiayi || 0, actor.system.social.exing || 0);
const tTag = getTag(args.target.system.social.xiayi || 0, args.target.system.social.exing || 0);

// 只有双方都有明显的、且互不相同的标签才触发（避免无标签和有标签被判定为“不同”）
if (myTag !== 'none' && tTag !== 'none' && myTag !== tTag) {
    args.flags.critThresholdMod += 2;
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="padding-left: 5px; border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.05);">
            <div style="font-weight:bold; color:#8e44ad;">道不同不相为谋</div>
            <div style="font-size:0.9em;">对 [${args.target.name}] 侠恶相斥，暴击阈值降低 2 点。</div>
        </div>`
    });
}

const myGender = actor.system.info.gender;
const tGender = args.target.system.info.gender;
if (myGender && tGender && myGender !== tGender) {
    args.config.amount += 10;
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="padding-left: 5px; border-left: 3px solid #e74c3c; background: rgba(231,76,60,0.05);">
            <div style="font-weight:bold; color:#e74c3c;">幽怨难鸣</div>
            <div style="font-size:0.9em;">对 [${args.target.name}] 性别相异，额外造成 10 点伤害。</div>
        </div>`
    });
}

if (args.isHit && args.isBroken) {
    const sysEffect = CONFIG.statusEffects.find(e => e.id === 'bunu');
    if(sysEffect) {
        const data = foundry.utils.deepClone(sysEffect);
        data.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, data);
        ui.notifications.info(`${args.target.name} 陷入 [不怒] 状态`);
    }
}

const effect = thisItem.effects.getName("诗酒").toObject();
delete effect._id;
effect.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effect);

if (args.isHit && !args.target.system.martial.stanceActive) {
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === 'shizhun'));
    if (effectData) {
        effectData.flags['xjzl-system'].maxStacks = 3;
        effectData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effectData);
    }
}

if (args.isHit) {
    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "jiuyi",
        dc: 13,
        label: "抵抗醉意",
        failureText: "抵抗失败！醉意增加 20 点。若因此进入醉倒或溢出，请手动应用[呕吐]状态并扣除饱食度。"
    });
}

if (args.isHit && args.item.name === '醉梦笔录' && args.target.system.resources?.alcohol) {
    const cur = args.target.system.resources.alcohol.value;
    await args.target.update({ 'system.resources.alcohol.value': cur + 5 });
    if (args.target.showFloatyText) {
        args.target.showFloatyText("醉意 +5", { fill: "#cc00ff" });
    }
}

if (args.isHit) {
    const effect = thisItem.effects.getName("梅").toObject();
    delete effect._id;
    effect.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effect);
}

if (args.isHit) {
    const effect = thisItem.effects.getName("兰").toObject();
    delete effect._id;
    effect.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effect);
}

if (args.isHit) {
    const effect = thisItem.effects.getName("竹").toObject();
    delete effect._id;
    effect.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effect);
}

if (args.isHit) {
    const effect = thisItem.effects.getName("菊").toObject();
    delete effect._id;
    effect.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effect);
}

let count = 0;
const input = await foundry.applications.api.DialogV2.prompt({
    window: { title: "消耗四君子状态" },
    content: `<p>请输入你要消耗的【梅/兰/竹/菊】状态总数 (0-4):</p><input type='number' name='count' min='0' max='4' value='0'>`,
    ok: { callback: (event, button, dialog) => button.form.elements.count.value },
    rejectClose: false
});
if (input === null) return;
count = parseInt(input) || 0;

const lvl = Math.max(1, move.computedLevel || 1);
const healPerStack = 10 + (lvl - 1) * 10;
const totalHeal = count * healPerStack;

if (totalHeal > 0) {
    await args.target.applyHealing({ healer: actor,  amount: totalHeal, type: 'hp', showScrolling: true });
    ui.notifications.info(`已消耗 ${count} 个状态。请务必手动删除你身上的对应状态卡牌！`);
    if (count === 4) {
        await args.target.applyHealing({ healer: actor,  amount: totalHeal, type: 'mp', showScrolling: true });
    }
}

// 给自己挂上 四君子 buff
const effect = thisItem.effects.getName("四君子").toObject();
delete effect._id;
effect.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effect);

if (Macros.checkStance(actor, args)) {
    const effect = thisItem.effects.getName("不语").toObject();
    delete effect._id;
    effect.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effect);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const effect = thisItem.effects.getName("不语").toObject();
    delete effect._id;
    effect.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effect);
}

const targets = Array.from(game.user.targets);
if (targets.length > 0) {
    await Macros.requestContest({
        attacker: actor,
        defender: targets[0].actor || targets[0],
        type: "qishu",
        label: "难分胜负 - 棋术对抗",
        outcome: {
            win: { text: "棋高一着！(请注意，你本次虚招值相当于结算+2)" },
            lose: { text: "平分秋色，对抗失败。" }
        }
    });
} else {
    const msg = `<div class="xjzl-chat-card" style="margin-left: 5px; border-left: 4px solid #8e44ad; background: rgba(142,68,173,0.05); padding: 5px;">
        <div style="color:#8e44ad; font-weight:bold;"><i class="fas fa-chess-board"></i> 难分胜负</div>
        <div style="font-size:0.9em; color:#555;">未选中目标。出招时请手动与防守方进行 <b>[棋术]</b> 对抗，若获胜则虚招值+2。</div>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (args.isHit) {
    const buyu = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'buyu');
    const stacks = buyu ? (buyu.getFlag('xjzl-system', 'stacks') || 0) : 0;
    if (stacks >= 3) {
        const roll = await actor.rollAttributeTest('qishu', { flavor: "一子定音 (DC10)" });
        if (roll && roll.total >= 10) {
            const jinshi = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "jinshi"));
            if(jinshi) {
                jinshi.duration = { rounds: 2 };
                await game.xjzl.api.effects.addEffect(args.target, jinshi);
                ui.notifications.info(`${args.target.name} 被落子镇压，陷入 [禁实] 2回合`);
            }
        }
    }
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const stacks = thisEffect.getFlag('xjzl-system', 'stacks') || 1;
if (stacks >= 3) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "满层不语爆发" },
        content: "<p>你已积攒满 3 层【不语】。</p><p>是否立即消耗所有层数，使本次武学招式伤害 <b>+20</b>？</p> (若未命中则同样消耗)",
        yes: { label: "消耗爆发", icon: "fas fa-fire" },
        no: { label: "保留不语", icon: "fas fa-times" }
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, thisEffect.id, 3);
        args.flags.damageResult.damage += 20;
        args.flags.damageResult.breakdown += "\n+ 满层不语: 20";
        actor.showFloatyText("不语爆发！", { fill: "#FFA500" });
    }
}

const effect = thisItem.effects.getName("颜体");
if (effect) {
    const effectData = effect.toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;

    const lvl = Math.max(1, move.computedLevel || 1);
    const ratio = 1 + (lvl - 1);

    // 存入当前招式等级的系数，供AE中读取运算
    foundry.utils.setProperty(effectData, "flags.xjzl-system.yanti_ratio", ratio);

    await game.xjzl.api.effects.addEffect(actor, effectData);
}

if (Macros.checkStance(actor, args)) {
    ui.notifications.info(`${actor.name} 触发力透纸背：可消耗反应动作对目标释放【笔下生风】`);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const blind = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === 'blind'));
    if (blind) {
        blind.duration = { rounds: 2 };
        await game.xjzl.api.effects.addEffect(args.target, blind);
        ui.notifications.info(`${args.target.name} 被笔锋迷眼，陷入目盲(2回合)！`);
    }
}

const isYanti = args.damageResult?.yantiTrigger;
const isLiuti = args.damageResult?.liutiTrigger;
let contentHtml = "";

if (isYanti) {
    contentHtml += "<li><span style='color:#c0392b;font-weight:bold;'>颜体刚猛</span>：将击中的敌人击飞 3 米！(请手动进行位移操作)</li>";
}
if (isLiuti) {
    await actor.applyHealing({ healer: actor,  amount: 20, type: 'huti', showScrolling: true });
    contentHtml += "<li><span style='color:#27ae60;font-weight:bold;'>柳体生息</span>：自身已获得 20 点护体真气！<br><span style='color:#555;'>(周围友方请手动操作增加 20 护体)</span></li>";
}

if (contentHtml !== "") {
    const msg = `<div class="xjzl-chat-card">
        <div style="font-weight:bold; border-bottom:1px solid #ccc; padding-bottom:3px; margin-bottom:5px;">
            <i class="fas fa-paint-brush"></i> 龙飞凤舞 意象触发
        </div>
        <ul style="padding-left: 20px; font-size: 0.9em; color: #444;">
            ${contentHtml}
        </ul>
    </div>`;
    ChatMessage.create({content: msg, speaker: ChatMessage.getSpeaker({actor: actor})});
}

const ratio = thisEffect.getFlag('xjzl-system', 'yanti_ratio') || 1;
const skillLevel = actor.system.skills.shuxie?.total || actor.system.arts.shuxie?.total || 0;
const bonus = skillLevel * ratio;
args.output.damage += bonus;
args.output.bonusDesc.push(`颜体增伤 +${bonus}`);

if (['waigong','neigong'].includes(args.move.damageType)) {
    const ratio = thisEffect.getFlag('xjzl-system', 'yanti_ratio') || 1;
    const liuti = thisItem.effects.getName("柳体");
    if (liuti) {
        const effData = liuti.toObject();
        delete effData._id;
        effData.origin = thisItem.uuid;
        foundry.utils.setProperty(effData, "flags.xjzl-system.liuti_ratio", ratio);
        await game.xjzl.api.effects.addEffect(actor, effData);
    }
    await thisEffect.delete();
    actor.showFloatyText("颜体 ➔ 柳体", {fill: "#3498db"});
}

if (['waigong','neigong'].includes(args.type)) {
    const ratio = thisEffect.getFlag('xjzl-system', 'liuti_ratio') || 1;
    const skillLevel = actor.system.skills.shuxie?.total || actor.system.arts.shuxie?.total || 0;
    const reduction = skillLevel * ratio;

    args.output.damage = Math.max(0, args.output.damage - reduction);

    const msg = `<div class="xjzl-chat-card"><div style="padding:5px; color:#27ae60;"><i class="fas fa-shield-alt"></i> 柳体护身，减免了 <b>${reduction}</b> 点伤害！</div></div>`;
    ChatMessage.create({content: msg, speaker: ChatMessage.getSpeaker({actor: actor})});
}

if (['waigong','neigong'].includes(args.type)) {
    const ratio = thisEffect.getFlag('xjzl-system', 'liuti_ratio') || 1;
    const yanti = thisItem.effects.getName("颜体");
    if (yanti) {
        const effData = yanti.toObject();
        delete effData._id;
        effData.origin = thisItem.uuid;
        foundry.utils.setProperty(effData, "flags.xjzl-system.yanti_ratio", ratio);
        await game.xjzl.api.effects.addEffect(actor, effData);
    }
    await thisEffect.delete();
    actor.showFloatyText("柳体 ➔ 颜体", {fill: "#e74c3c"});
}

if (args.isHit) {
    const roll = await actor.rollAttributeTest('zuohua');
    if (roll.total >= 10) {
        ui.notifications.info("作画成功，在目标脚下生成‘琼楼’（请放置模板）");
    }
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const effect = CONFIG.statusEffects.find(e => e.id === 'fali');
    const data = foundry.utils.deepClone(effect);
    data.flags['xjzl-system'].maxStacks = 3;
    await game.xjzl.api.effects.addEffect(args.target, data);
}

if (Macros.checkStance(actor, args)) {
    ui.notifications.info("格挡成功，在攻击者脚下生成‘琼楼’（请放置模板）");
}

if (Macros.checkStance(actor, args)) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const effectData = thisItem.effects.getName("弈理").toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    // 核心：把当前架招对应的等级传给 AE，让 AE 在 Passive 阶段能读到它！
    effectData.flags["xjzl-system"].stanceLevel = lvl;
    await game.xjzl.api.effects.addEffect(actor, effectData);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const msg = `<div class="xjzl-chat-card" style="margin-left: 5px; border-left: 4px solid #e67e22; background: rgba(230,126,34,0.05); padding: 5px;">
        <div style="font-weight:bold; color:#e67e22;"><i class="fas fa-wind"></i> 飞联气贯</div>
        <div style="font-size:0.9em; color:#555;">目标 <b>${args.target.name}</b> 被朝任意方向击飞 <span style="font-weight:bold; color:red;">2 米</span>！</div>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

if (!args.isHit) return;

const chizhi = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "chizhi"));
if (!chizhi) return;

// 情况A: 成功击破了架招
if (args.isBroken) {
    chizhi.duration = { rounds: 3 };
    await game.xjzl.api.effects.addEffect(args.target, chizhi);
    return;
}

// 情况B: 没破掉（虚招对抗失败），此时对方一定有架招
if (args.target.system.martial.stanceActive) {
    chizhi.duration = { rounds: 1 }; // 这里设为1回合供底下自动发卡使用
    await Macros.requestContest({
        attacker: actor,
        defender: args.target,
        type: "qishu",
        label: "变胜先手 - 棋术对抗(补救)",
        outcome: {
            win: {
                 text: "反将一军！目标陷入迟滞 (1回合)。",
                 targetEffect: chizhi  // 直接传对象，附带正确的回合数
            },
            lose: { text: "对方棋路严密，未能反制。" }
        }
    });
} else {
    // 兜底：如果完全没有目标，或者其它未知异常
    const msg = `<div class="xjzl-chat-card" style="margin-left: 5px; border-left: 4px solid #8e44ad; background: rgba(142,68,173,0.05); padding: 5px;">
        <div style="color:#8e44ad; font-weight:bold;"><i class="fas fa-chess"></i> 变胜先手 (未找到目标架招)</div>
        <div style="font-size:0.9em; color:#555;">如果虚招被压制，可手动与其进行[棋术]对抗，获胜附加1回合迟滞。</div>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
}

const yili = actor.effects.find(e => e.getFlag('xjzl-system', 'slug') === 'yili');
if (yili) {
    await yili.delete();
    const lvl = Math.max(1, move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);
    const msg = `<div class="xjzl-chat-card" style="margin-left: 5px; border-left: 4px solid #8e44ad; background: rgba(142,68,173,0.05); padding: 5px;">
        <div style="font-weight:bold; color:#8e44ad;"><i class="fas fa-chess-board"></i> 渊微降临</div>
        <div style="font-size:0.9em; color:#555;">已消耗 [弈理]。请在周围布下【渊微】区域，持续 <b>${rounds}</b> 回合。</div>
        <hr>
        <ul style="font-size: 0.85em; color: #666; padding-left: 15px; margin-bottom: 0;">
            <li>敌人无法离开此区域</li>
            <li>施法者处于区域内时：每回合初额外获得一个主要动作</li>
        </ul>
    </div>`;
    ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({actor: actor}) });
} else {
    ui.notifications.warn("未检测到【弈理】状态，无法施展此绝招！");
    args.flags.abort = true;
    args.flags.abortReason = "缺少必要的 [弈理] 状态。";
}

const lvl = thisEffect.getFlag('xjzl-system', 'stanceLevel') || 1;
const bonus = 1 + (lvl - 1);

// 动态为每一个属性技能附加检定加值
if (S.skills) {
    for (const key of Object.keys(CONFIG.XJZL.skills)) {
        if (S.skills[key]) S.skills[key].checkMod += bonus;
    }
}

// 动态为每一个技艺技能附加检定加值
if (S.arts) {
    for (const key of Object.keys(CONFIG.XJZL.arts)) {
        if (S.arts[key]) S.arts[key].checkMod += bonus;
    }
}

const lvl = Math.max(1, args.move.computedLevel || 1);
const diff = 15 + (lvl - 1);
const rounds = 1 + (lvl - 1);

const hasRoot = args.target.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'root');
const targetEffectId = hasRoot ? 'blind' : 'root';

const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === targetEffectId));
if (effectData) {
    effectData.duration = { rounds: rounds };
}

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: "dingli",
    dc: diff,
    label: "抵抗粉墙黛瓦",
    onFail: effectData
});

if (Macros.checkStance(actor, args)) {
    await actor.applyHealing({ healer: actor,  amount: 5, type: 'mp', showScrolling: true });

    const msg = `<div class="xjzl-chat-card">
        <div style="padding:5px; border-left:3px solid #3498db; background:rgba(52,152,219,0.1);">
            <p><i class="fas fa-music"></i> <b>小桥流水</b> 格挡生效！</p>
            <p>自身已回复 5 点内力。<span style="color:#d35400;">请周围 1 米内友方手动回复 5 点内力。</span></p>
        </div>
    </div>`;
